test('accepts exact 304 revalidation and independently derives repeat receipt entry',()=>{const f=fixture('cache');markRevalidated(f,1,'preview');const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,true,JSON.stringify(out.errors));});
test('accepts exact degraded first-task 304 revalidation',()=>{const f=fixture();markRevalidated(f,0,'preview');const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,true,JSON.stringify(out.errors));});
test('preserves historical no-cache degraded CSS without validators',()=>{const f=fixture();for(const task of f.r.tasks)for(const response of task.responses.filter(x=>x.path==='/static/app.css')){delete response.headers.etag;delete response.headers['cache-control'];}for(const event of f.r.transport.guard_coverage.rawNetworkEvents)if(event.method==='Network.responseReceived'||event.method==='Network.responseReceivedExtraInfo')event.params.headers?event.params.headers={}:event.params.response.headers={};refreshFixtureEvidence(f);const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,true,JSON.stringify(out.errors));});
test('allows absent repeat-revalidation field when none occurred',()=>{const f=fixture('cache');delete f.r.transport.cache_repeat_revalidations;const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,true,JSON.stringify(out.errors));});
const cases=[
  ['wrong rule',({r})=>{r.transport.guard_coverage.rawNetworkEvents.find(e=>e.method==='Network.requestWillBeSentExtraInfo').params.appliedNetworkConditionsId='wrong';},'missing/wrong shaping rule'],
  ['unshaped iframe',({r})=>{r.transport.guard_coverage.sessions.push({sessionId:'iframe',type:'iframe',waitingForDebugger:true,recursiveAutoAttach:true,networkEnabled:true,blockedURLs:true,appliedPolicy:true,ruleIds:[],resumed:true,error:null});},'unshaped guarded target'],
  ['missing event',({r})=>{const raw=r.transport.guard_coverage.rawNetworkEvents,i=raw.findIndex(e=>e.method==='Network.responseReceived');raw.splice(i,1);r.transport.guard_events.splice(i,1);r.transport.guard_event_count--;},'incomplete CDP lineage'],
  ['zero byte failure',({r})=>{r.tasks[0].responses[0].sizes.responseBodySize=0;},'zero response wire bytes'],
  ['unreported unpaused session',({r})=>{r.transport.guard_coverage.sessions[0].waitingForDebugger=false;},'unpaused attachment summary'],
  ['bad CDP status',({r})=>{r.transport.guard_coverage.rawNetworkEvents.find(e=>e.method==='Network.responseReceived').params.response.status=500;},'CDP response URL/status'],
  ['invalid download completion',({r})=>{const t=r.tasks[0],start=t.cdp_boundaries.export.start,end=t.cdp_boundaries.export.end,e=r.transport.guard_coverage.rawNetworkEvents.slice(start,end).find(x=>x.method==='Network.loadingFinished');e.method='Network.loadingFailed';e.params.errorText='net::ERR_FAILED';e.params.canceled=false;},'invalid completion lineage'],
  ['missing response policy',({r})=>{delete r.tasks[0].responses[0].headers['cache-control'];},'editor response policy'],
  ['unknown request session',({r})=>{const e=r.transport.guard_coverage.rawNetworkEvents.find(e=>e.method==='Network.requestWillBeSent');e.sessionId='unknown';},'request on unknown session'],
  ['overlapping contexts',({r})=>{r.contexts[1].network_events_start=r.contexts[0].network_events_end-1;},'event order/overlap'],
  ['missing matrix task',({r})=>{r.tasks.pop();},'task/context matrix count'],
  ['NaN timing',({r})=>{r.tasks[0].timings_ms.preview=NaN;},'preview ms'],
  ['over budget',({r})=>{r.tasks[0].timings_ms.preview=2501;},'preview ms'],
  ['changed source',({r})=>{r.source.after_sha256='b'.repeat(64);},'source changed'],
];
for(const [name,mutate,want]of cases)test('rejects '+name,()=>{const f=fixture();mutate(f);const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes(want)),JSON.stringify(out.errors));});
test('rejects absent cache event',()=>{const f=fixture('cache'),raw=f.r.transport.guard_coverage.rawNetworkEvents;for(const event of raw){if(event.method==='Network.requestServedFromCache'){event.method='Network.policyUpdated';event.params={};}if(event.method==='Network.responseReceived')event.params.response.fromDiskCache=false;if(event.method==='Network.responseReceivedExtraInfo')event.params.statusCode=200;}f.r.transport.guard_events=raw.map(e=>({kind:'network',...e}));f.r.transport.guard_event_count=raw.length;f.r.transport.cache_repeat_hits=[];const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('repeat cache provenance absent')),JSON.stringify(out.errors));});
test('rejects wrong derived cache-event index',()=>{const f=fixture('cache');f.r.transport.cache_repeat_hits[0].event_index--;const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('derived cache hits differ')),JSON.stringify(out.errors));});
test('rejects stray raw request outside all contexts',()=>{const f=fixture(),raw=f.r.transport.guard_coverage.rawNetworkEvents,e={sessionId:f.r.transport.guard_coverage.sessions[0].sessionId,method:'Network.requestWillBeSent',params:{requestId:'stray',request:{method:'GET',url:origin+'/static/app.css'}}};raw.push(e);f.r.transport.guard_events.push({kind:'network',...e});f.r.transport.guard_event_count++;const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(x=>x.includes('outside/overlapping contexts')),JSON.stringify(out.errors));});
for(const [name,mutate]of [['wrong parent',x=>x.child.parentSessionId='wrong'],['wrong frame',x=>x.child.targetId='wrong'],['reused request id on unrelated session',x=>x.completion.sessionId=x.request.sessionId+'-unrelated'],['ambiguous matching child',x=>{const copy=structuredClone(x.child);copy.sessionId+='-duplicate';x.coverage.sessions.push(copy);if(copy.ruleIds.length)x.coverage.ruleIds.push({sessionId:copy.sessionId,ruleId:copy.ruleIds[0]});}]])test('rejects OOPIF handoff '+name,()=>{const f=fixture(),x=withHandoff(f);x.coverage=f.r.transport.guard_coverage;mutate(x);f.r.transport.guard_events=x.coverage.rawNetworkEvents.map(e=>({kind:'network',...e}));const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('invalid completion lineage')),JSON.stringify(out.errors));});
test('rejects missing frozen phase-wait identity',()=>{const f=withPhaseBarrier(fixture());delete f.r.identities.phase_wait;const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('identity phase_wait')),JSON.stringify(out.errors));});
test('rejects phase completed before response body',()=>{const f=withPhaseBarrier(fixture());f.r.tasks[0].phase_clock.navigation.completed_ms=2;f.r.tasks[0].timings_ms.navigation=2;const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('completed before response body')),JSON.stringify(out.errors));});
test('rejects phase clock/timing mismatch',()=>{const f=withPhaseBarrier(fixture());f.r.tasks[0].phase_clock.navigation.completed_ms+=1;const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('phase timing mismatch')),JSON.stringify(out.errors));});
test('rejects unpinned phase-barrier claim',()=>{const f=fixture();f.r.acquisition={complete_phase_barrier:true};const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('barrier/helper')),JSON.stringify(out.errors));});
test('rejects cache reuse before any causal body',()=>{const f=fixture();markDiskCache(f,0,'navigation');const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('missing causal same-context')),JSON.stringify(out.errors));});
test('rejects cache reuse borrowed from another context',()=>{const f=fixture();markDiskCache(f,1,'navigation');const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('missing causal same-context')),JSON.stringify(out.errors));});
test('rejects prior response that completed after current request began',()=>{const f=fixture(),prior=f.r.tasks[0].responses.find(x=>x.phase==='navigation'&&x.path==='/static/app.css');prior.finished_ms=999;markDiskCache(f,0,'preview');const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('missing causal same-context')),JSON.stringify(out.errors));});
test('rejects prior body from a different URL in the same context',()=>{const f=fixture(),x=cssLineage(f,0,'navigation'),changed=x.request.params.request.url+'?old=1';x.request.params.request.url=changed;x.received.params.response.url=changed;const request=x.task.requests.find(q=>q.phase==='navigation'&&q.path==='/static/app.css'),response=x.task.responses.find(r=>r.phase==='navigation'&&r.path==='/static/app.css');request.url=changed;response.url=changed;markDiskCache(f,0,'preview');const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('missing causal same-context')),JSON.stringify(out.errors));});
test('rejects wrong 304 response ETag',()=>{const f=fixture('cache');markRevalidated(f,1,'preview');cssLineage(f,1,'preview').responseExtra.params.headers.ETag='"wrong"';const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('ETag/conditional mismatch')),JSON.stringify(out.errors));});
test('rejects wrong 304 conditional',()=>{const f=fixture('cache');markRevalidated(f,1,'preview');cssLineage(f,1,'preview').extra.params.headers['If-None-Match']='"wrong"';const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('ETag/conditional mismatch')),JSON.stringify(out.errors));});
test('rejects wrong raw cached response ETag',()=>{const f=fixture('cache');markDiskCache(f,0,'preview');cssLineage(f,0,'preview').received.params.response.headers.ETag='"wrong"';const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('cached CSS response validator binding')),JSON.stringify(out.errors));});
test('rejects missing retained prior body',()=>{const f=fixture('cache'),prior=f.r.tasks[0].responses.find(x=>x.phase==='navigation'&&x.path==='/static/app.css');prior.body_evidence=null;markRevalidated(f,0,'preview');const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('missing causal same-context')),JSON.stringify(out.errors));});
test('rejects cache event for no-store preview document',()=>{const f=fixture('cache'),task=f.r.tasks[0],boundary=task.cdp_boundaries.preview,slice=f.r.transport.guard_coverage.rawNetworkEvents.slice(boundary.start,boundary.end),response=task.responses.find(x=>x.phase==='preview'&&x.path==='/theme-lab/preview'),event=slice.find(x=>x.method==='Network.responseReceived'&&x.params.response.url===response.url);event.params.response.fromDiskCache=true;refreshFixtureEvidence(f);const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('forbidden cache lineage')),JSON.stringify(out.errors));});
test('rejects fake unbound 304 event',()=>{const f=fixture('cache'),event=f.r.transport.guard_coverage.rawNetworkEvents.find(x=>x.method==='Network.responseReceivedExtraInfo');event.params.statusCode=304;event.params.requestId='fake';refreshFixtureEvidence(f);const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('unbound 304 event')),JSON.stringify(out.errors));});
test('rejects fake unbound served-cache event',()=>{const f=fixture('cache'),event=f.r.transport.guard_coverage.rawNetworkEvents.find(x=>x.method==='Network.requestServedFromCache');event.params.requestId='fake';refreshFixtureEvidence(f);const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('unbound served-cache event')),JSON.stringify(out.errors));});
test('fresh-task cache alone does not satisfy repeat evidence',()=>{const f=fixture('cache');clearRepeatCache(f);markDiskCache(f,0,'preview');const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('repeat cache provenance absent')),JSON.stringify(out.errors));});
test('rejects absent repeat-revalidation field when a 304 occurred',()=>{const f=fixture('cache');markRevalidated(f,1,'preview');delete f.r.transport.cache_repeat_revalidations;const out=checkReceipt(f.r,{snapshot:f.snapshot});assert.equal(out.ok,false);assert(out.errors.some(e=>e.includes('derived cache revalidations differ')),JSON.stringify(out.errors));});
